.ends SUB_1

* Input source: 500mV to 900mV pulse (Fig. 24.24), with AC=1 for frequency response
Vin vin 0 pulse(0.5 0.9 450n 1n 1n 100n 1u) dc 0.7 ac 1

.control
* 1. Operating Point
op
let power = -i(VDD) * 1.8
print power

* 2. AC Analysis (Closed-loop follower bandwidth)
ac dec 100 1k 1G
let cl_gain = vdb(vout)
let cl_phase = 180/PI * cph(v(vout))
meas ac dc_gain find cl_gain at=1k
meas ac f_3dB when cl_gain=-3 fall=1
print dc_gain f_3dB

* 3. Transient Analysis (Baker Ch 24 Fig. 24.24)
tran 0.1n 700n 400n
meas tran v_init find v(vout) at=440n
meas tran v_peak max v(vout) from=450n to=550n
meas tran v_trough min v(vout) from=550n to=700n
meas tran t_rise_10 trig v(vout) val=0.54 rise=1 targ v(vout) val=0.86 rise=1
let sr_rising = 0.32 / (t_rise_10 * 1e6)
print sr_rising
meas tran t_fall_10 trig v(vout) val=0.86 fall=1 targ v(vout) val=0.54 fall=1
let sr_falling = 0.32 / (t_fall_10 * 1e6)
print sr_falling
meas tran t_settle_low_high trig v(vin) val=0.7 rise=1 targ v(vout) val=0.89 rise=1
meas tran t_settle_high_low trig v(vin) val=0.7 fall=1 targ v(vout) val=0.51 fall=1
print t_settle_low_high t_settle_high_low

quit
.endc
.end

